/** Dependency-free instrumentation. Uses its own disposable database and the QA package. */
public final class QARunner extends Instrumentation {
    int count=0;StringBuilder ledger=new StringBuilder();boolean persistOnly=false;
    void check(boolean condition,String label){if(!condition)throw new AssertionError(label);count++;ledger.append("PASS ").append(count).append(" ").append(label).append('\n');}
    void rejects(Runnable action,String label){boolean rejected=false;try{action.run();}catch(IllegalArgumentException expected){rejected=true;}check(rejected,label);}
    @Override public void onCreate(Bundle arguments){super.onCreate(arguments);persistOnly=arguments!=null&&"true".equals(arguments.getString("persistOnly"));start();}
    @Override public void onStart(){Bundle result=new Bundle();try{if(persistOnly)persistenceSmoke();else{domain();ui();}result.putString("stream","\n"+ledger+"\nOK "+count+" device assertions\n");result.putInt("assertions",count);finish(Activity.RESULT_OK,result);}catch(Throwable error){StringWriter trace=new StringWriter();error.printStackTrace(new PrintWriter(trace));result.putString("stream","\n"+ledger+"FAIL "+trace);finish(Activity.RESULT_CANCELED,result);}}
    JSONObject profile(){return Store.object("id","local","name","آزمون آفلاین","grade",8,"field","عمومی","scale",20,"dailyGoal",90,"demo",false);}
    JSONObject subject(String id,String name){return Store.object("id",id,"name",name,"color","#6C5CE7","archived",false);}
    JSONObject exam(String id,String subject,Double grade,double max,Double weight){return Store.object("id",id,"subjectId",subject,"title","آزمون "+id,"date",Dates.today(),"grade",grade,"maxGrade",max,"weight",weight,"notes","");}
    JSONObject session(String id,String series){return Store.object("id",id,"subjectId","math","title","مرور","date",Dates.today(),"time","16:30","duration",45,"completed",false,"seriesId",series,"kind","مطالعه","priority","مهم","notes","");}
    void domain()throws Exception{
        Context context=getTargetContext();String filename="qa-domain-tests.db";context.deleteDatabase(filename);Store db=new Store(context,filename);
        try{
            check(!db.hasProfile(),"Fresh database has no fabricated user/demo data");db.getWritableDatabase().execSQL("CREATE TRIGGER qa_onboard_failure BEFORE INSERT ON entries WHEN NEW.category='subjects' BEGIN SELECT RAISE(IGNORE); END");boolean onboardingFailed=false;try{db.onboard(profile(),Arrays.asList(subject("math","ریاضی"),subject("science","علوم")));}catch(android.database.SQLException expected){onboardingFailed=true;}finally{db.getWritableDatabase().execSQL("DROP TRIGGER qa_onboard_failure");}check(onboardingFailed&&!db.hasProfile()&&db.all("subjects").isEmpty(),"Onboarding subjectwritefailure rollsbackprofileandpresets");db.onboard(profile(),Arrays.asList(subject("math","ریاضی"),subject("science","علوم"),subject("zero","صفر واقعی")));
            check(db.hasProfile(),"Profile persisted");db.save("exams",exam("one","math",20d,20,2d));db.save("exams",exam("two","math",40d,100,null));db.save("exams",exam("pending","math",null,20,null));db.save("exams",exam("science-grade","science",12d,20,null));
            check(Math.abs(db.subjectAverages("1921-01-01","2122-12-31").get("math")-80)<.00001,"Mixed scales/weights yield80; missing grade excluded");check(Math.abs(db.average("1921-01-01","2122-12-31")-70)<.00001,"Overall equally weights subjects");
            db.save("exams",exam("zero-grade","zero",0d,20,null));check(Math.abs(db.average("1921-01-01","2122-12-31")-46.6666667)<.00001,"Earnedzero included rather than treated asmissing");
            rejects(()->db.save("exams",exam("bad","math",21d,20,null)),"Grade above maximum rejected");rejects(()->db.save("subjects",subject("math2"," ریاضی ")),"Trimmedduplicate subject name rejected");
            JSONObject report=Store.object("id","report-one","date",Dates.today(),"subjects",new JSONArray().put(Store.object("subjectId","math","minutes",70,"note","تمرین")),"tasks",new JSONArray().put(Store.object("title","حل تمرین","subjectId","math","completed",true)).put(Store.object("title","مرور","subjectId","","completed",false)),"lessons","فصل یک","exercises","تمرین","difficulties","","reflection","یک قدم جلوتر","nextGoals","مرور فردا");db.save("reports",report);
            check(db.totalMinutes(Dates.today(),Dates.today())==70,"Report minutes persist");check(db.tasks(Dates.today(),Dates.today(),true)==1&&db.tasks(Dates.today(),Dates.today(),false)==1,"Completed/pending tasks remain distinct");
            JSONObject excessive=Store.copy(report);excessive.put("id","report-too-much");excessive.getJSONArray("subjects").getJSONObject(0).put("minutes",1400);rejects(()->db.save("reports",excessive),"Daily total above1440 rejected across reports");
            JSONObject goal=Store.object("id","goal","title","هدف","metric","minutes","period","weekly","target",100,"start",java.time.LocalDate.parse(Dates.today()).plusDays(40).toString(),"end",java.time.LocalDate.parse(Dates.today()).plusDays(70).toString(),"active",true);db.save("goals",goal);check(db.goalValue(goal,Dates.today())==0,"Futuregoal disjoint period yieldszero");
            goal.put("start",Dates.today());goal.put("end",Dates.today());db.save("goals",goal);check(db.goalValue(goal,Dates.today())==70,"Goal clips tovalidintersection");
            check(Dates.iso(1405,7,27).equals("2026-10-19"),"JalalitoGregorian reference conversion");check(Arrays.equals(Dates.jalali("2026-10-19"),new int[]{1405,7,27}),"GregoriantoJalali reference conversion");check(Dates.iso(1403,12,30).equals("2025-03-20"),"LeapEsfand30 accepted");rejects(()->Dates.iso(1404,12,30),"NonleapEsfand30 rejected");rejects(()->Dates.iso(1405,7,31),"Invalid31Mehr rejected");String[] month=Dates.period("2026-10-19","monthly");check(month[0].equals(Dates.iso(1405,7,1))&&month[1].equals(Dates.iso(1405,7,30)),"Monthlyreport usesPersianmonth boundaries");
            String[] lastMonth=Dates.period(Dates.iso(1500,12,15),"monthly");int[] lastDay=Dates.jalali(lastMonth[1]);check(lastMonth[0].equals(Dates.iso(1500,12,1))&&lastDay[0]==1500&&lastDay[1]==12,"UpperJalali1500Esfand monthlyboundary doesnotcrash");check(Dates.period(Dates.iso(1300,1,1),"monthly")[0].equals(Dates.iso(1300,1,1)),"LowerJalali1300monthlyboundary isvalid");
            String backup=db.exportJson();check(db.validateBackup(backup).get("reports").size()==1,"Validbackup passes fullvalidation");JSONObject oldDate=new JSONObject(backup);oldDate.getJSONObject("data").getJSONArray("exams").getJSONObject(0).put("date","1921-01-01");rejects(()->db.importJson(oldDate.toString()),"BackupbeforeJalali1300 isrejected");JSONObject lateDate=new JSONObject(backup);lateDate.getJSONObject("data").getJSONArray("exams").getJSONObject(0).put("date","2122-12-31");rejects(()->db.importJson(lateDate.toString()),"BackupafterJalali1500 isrejected");JSONObject invalid=new JSONObject(backup);invalid.getJSONObject("data").getJSONArray("subjects").put(subject("duplicate"," ریاضی "));rejects(()->db.importJson(invalid.toString()),"Backupduplicate trimmedname rejected");check(db.all("reports").size()==1,"Failedvalidation preservesexistingrecords");
            JSONObject orphan=new JSONObject(backup);orphan.getJSONObject("data").getJSONArray("exams").getJSONObject(0).put("subjectId","missing");rejects(()->db.importJson(orphan.toString()),"Orphanreference rejectedbeforewrite");
            JSONObject failure=new JSONObject(backup);JSONObject triggerGoal=Store.copy(goal);triggerGoal.put("id","failure-record");failure.getJSONObject("data").getJSONArray("goals").put(triggerGoal);db.getWritableDatabase().execSQL("CREATE TRIGGER qa_insert_failure BEFORE INSERT ON entries WHEN NEW.id='failure-record' BEGIN SELECT RAISE(IGNORE); END");boolean failed=false;try{db.importJson(failure.toString());}catch(android.database.SQLException expected){failed=true;}finally{db.getWritableDatabase().execSQL("DROP TRIGGER qa_insert_failure");}check(failed,"SilentSQLiteinsertfailure becomesexception");check(db.all("reports").size()==1&&db.get("goals","failure-record")==null,"Importwritefailure rollsbackwhole replacement");
            db.saveSessions(Arrays.asList(session("series-first","series"),session("series-second","series")));db.getWritableDatabase().execSQL("CREATE TRIGGER qa_delete_failure BEFORE DELETE ON entries WHEN OLD.id='series-first' BEGIN SELECT RAISE(ABORT,'qa deliberate failure'); END");failed=false;try{db.removeSeries("series");}catch(android.database.SQLException expected){failed=true;}finally{db.getWritableDatabase().execSQL("DROP TRIGGER qa_delete_failure");}check(failed&&db.all("sessions").size()==2,"Seriesdelete failure rollsbackearlierdeletion");db.removeSeries("series");check(db.all("sessions").isEmpty(),"Seriesdelete succeeds atomically");
            JSONObject archived=db.get("subjects","math");archived.put("archived",true);db.save("subjects",archived);check(db.subjectName("math").equals("ریاضی")&&db.get("exams","one")!=null,"Archivingpreserveshistoricalrecords");db.importJson(backup);check(db.get("subjects","math").optBoolean("archived")==false,"Validrestore replacesstate");
            Store reopened=new Store(context,filename);check(reopened.get("reports","report-one")!=null,"Data persists onindependentSQLiteconnection");reopened.close();
            ReportData data=new ReportData(db,Dates.today(),"weekly");check(data.lines.size()>10&&data.minutes==70,"Reportcard generatedfromrealrecords");rejects(db::seedDemo,"Demoseed cannot overwrite existingprofile");
        }finally{db.close();context.deleteDatabase(filename);}
    }
    List<EditText> inputs(View view){List<EditText> list=new ArrayList<>();if(view instanceof EditText)list.add((EditText)view);if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)list.addAll(inputs(((ViewGroup)view).getChildAt(i)));return list;}
    boolean hasLabel(View view,int id){if(view instanceof TextView&&view.getLabelFor()==id)return true;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)if(hasLabel(((ViewGroup)view).getChildAt(i),id))return true;return false;}
    Button findButton(View view,String prefix){if(view instanceof Button&&((Button)view).getText().toString().startsWith(prefix))return(Button)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){Button result=findButton(((ViewGroup)view).getChildAt(i),prefix);if(result!=null)return result;}return null;}
    void ui()throws Exception{
        Intent intent=new Intent(Intent.ACTION_MAIN);intent.setComponent(new ComponentName(getTargetContext().getPackageName(),MainActivity.class.getName()));intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity activity=(MainActivity)startActivitySync(intent);waitForIdleSync();
        runOnMainSync(()->{if(!activity.store.hasProfile()){List<EditText> fields=inputs(activity.root);fields.get(0).setText("آزمون بومی ستاره");Button create=findButton(activity.root,"ساخت دفتر");if(create==null)throw new AssertionError("Onboardingbutton missing");create.performClick();}check(activity.store.hasProfile(),"Nativeonboarding creates localprofile");check(activity.root.getLayoutDirection()==View.LAYOUT_DIRECTION_RTL,"Native rootusesRTL");activity.forms.report(null);View formRoot=activity.ui.lastDialog.getWindow().getDecorView();List<EditText> fields=inputs(formRoot);check(fields.stream().allMatch(field->field.getId()!=View.NO_ID&&hasLabel(formRoot,field.getId())),"Native formfields have explicitaccessiblelabels");fields.get(0).setText("۴۵");fields.get(4).setText("[x] تمرین رابط\n[ ] مرور رابط");activity.ui.lastDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();check(!activity.store.all("reports").isEmpty(),"Native reportform savesPersianminutes andtasks");});waitForIdleSync();
        runOnMainSync(()->{activity.forms.exam(null);List<EditText> fields=inputs(activity.ui.lastDialog.getWindow().getDecorView());fields.get(0).setText("آزمون رابط کاربری");fields.get(1).setText("۱۸");fields.get(2).setText("۲۰");fields.get(3).setText("۲");activity.ui.lastDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();check(activity.store.all("exams").stream().anyMatch(exam->exam.optString("title").equals("آزمون رابط کاربری")),"Nativeexamform saves weightedgrade");activity.forms.session(null);fields=inputs(activity.ui.lastDialog.getWindow().getDecorView());fields.get(0).setText("مطالعهٔ رابط");activity.ui.lastDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();check(!activity.store.all("sessions").isEmpty(),"Nativeplannerform saves independent session");activity.forms.goal(null);fields=inputs(activity.ui.lastDialog.getWindow().getDecorView());fields.get(0).setText("هدف رابط");activity.ui.lastDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();check(!activity.store.all("goals").isEmpty(),"Nativegoalform saves persistentgoal");});waitForIdleSync();
        runOnMainSync(()->{
            try{JSONObject report=activity.store.all("reports").get(0);JSONArray rows=report.getJSONArray("subjects"),tasks=report.getJSONArray("tasks");String subjectId=rows.getJSONObject(0).getString("subjectId");rows.getJSONObject(0).put("note","یادداشت واردشده باید بماند");tasks.getJSONObject(0).put("subjectId",subjectId);activity.store.save("reports",report);activity.forms.report(report);activity.ui.lastDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();JSONObject saved=activity.store.get("reports",report.getString("id"));check(saved.getJSONArray("subjects").getJSONObject(0).getString("note").equals("یادداشت واردشده باید بماند"),"Editingreport preserves importedsubjectnotes");check(saved.getJSONArray("tasks").getJSONObject(0).getString("subjectId").equals(subjectId),"Editingunchangedtask preserves subjectassociation");
                JSONObject task=saved.getJSONArray("tasks").getJSONObject(0);boolean previous=task.getBoolean("completed");CheckBox checkbox=new CheckBox(activity);checkbox.setChecked(previous);activity.screens.persistCheck(checkbox,"reports",saved,task);activity.store.getWritableDatabase().execSQL("CREATE TRIGGER qa_checkbox_failure BEFORE INSERT ON entries WHEN NEW.category='reports' BEGIN SELECT RAISE(IGNORE); END");try{checkbox.setChecked(!previous);check(checkbox.isChecked()==previous&&task.getBoolean("completed")==previous,"Failedreportcheckboxwrite revertsUIandmemory");}finally{activity.store.getWritableDatabase().execSQL("DROP TRIGGER qa_checkbox_failure");}
                JSONObject session=activity.store.all("sessions").get(0);boolean wasDone=session.getBoolean("completed");CheckBox sessionBox=new CheckBox(activity);sessionBox.setChecked(wasDone);activity.screens.persistCheck(sessionBox,"sessions",session,session);activity.store.getWritableDatabase().execSQL("CREATE TRIGGER qa_session_checkbox_failure BEFORE INSERT ON entries WHEN NEW.category='sessions' BEGIN SELECT RAISE(IGNORE); END");try{sessionBox.setChecked(!wasDone);check(sessionBox.isChecked()==wasDone&&session.getBoolean("completed")==wasDone,"Failedsessioncheckboxwrite revertsUIandmemory");}finally{activity.store.getWritableDatabase().execSQL("DROP TRIGGER qa_session_checkbox_failure");}
            }catch(JSONException error){throw new IllegalStateException(error);}
            for(String screen:Arrays.asList("home","reports","exams","planner","goals","cards","subjects","settings","more")){activity.navigate(screen);check(activity.content.getChildCount()>0,"Native screenrenders: "+screen);}ReportData report=new ReportData(activity.store,Dates.today(),"weekly");byte[] pdf=activity.exporter.buildPdf(report.lines);check(pdf.length>1000&&new String(pdf,0,4).equals("%PDF"),"NativePDF outputcontainsrealPDFbytes");
            List<String> longReport=new ArrayList<>();for(int i=0;i<120;i++)longReport.add("صفحهٔ آزمایشی "+i+" • متن فارسی برای آزمون انتخاب بازهٔ چاپ و خوانایی کارنامه");Exporter.PdfResult full=activity.exporter.renderPdf(longReport,null),selected=activity.exporter.renderPdf(longReport,new android.print.PageRange[]{new android.print.PageRange(1,1)});check(full.pageCount>2&&selected.included.equals(Collections.singletonList(1)),"PDF renderer honorsrequestedpage range");try{File pdfFile=new File(getTargetContext().getCacheDir(),"qa-selected.pdf");try(FileOutputStream output=new FileOutputStream(pdfFile)){output.write(selected.bytes);}try(android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(ParcelFileDescriptor.open(pdfFile,ParcelFileDescriptor.MODE_READ_ONLY))){check(renderer.getPageCount()==1,"SelectedrangePDF hasexactlyonerealpage");}}catch(IOException error){throw new IllegalStateException(error);}activity.navigate("planner");activity.back();check(activity.screen.equals("home"),"Nativeback returnsfromsecondaryscreen tohome");
        });waitForIdleSync();
        // Dismiss a first-boot emulator System UI ANR via the instrumentation accessibility API.
        // This is test-device setup, not an app feature or an adb input workaround.
        dismissEmulatorDialog();
        waitForIdleSync();capture("qa-home.png");
        for(String screen:Arrays.asList("exams","planner","cards","settings")){runOnMainSync(()->activity.navigate(screen));waitForIdleSync();getUiAutomation().waitForIdle(500,10000);capture("qa-"+screen+".png");}
        runOnMainSync(()->{ReportData report=new ReportData(activity.store,Dates.today(),"weekly");try(FileOutputStream output=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"qa-report-card.pdf"))){output.write(activity.exporter.buildPdf(report.lines));}catch(IOException error){throw new IllegalStateException(error);}activity.navigate("home");});waitForIdleSync();
        try(FileOutputStream output=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"qa-ledger.txt"))){output.write(ledger.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    }
    void capture(String filename)throws IOException{Bitmap shot=getUiAutomation().takeScreenshot();if(shot!=null){try(FileOutputStream output=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),filename))){shot.compress(Bitmap.CompressFormat.PNG,100,output);}shot.recycle();check(true,"Native screenshot captured: "+filename);}}
    void dismissEmulatorDialog()throws Exception{android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;getUiAutomation().setServiceInfo(info);for(android.view.accessibility.AccessibilityWindowInfo window:getUiAutomation().getWindows()){android.view.accessibility.AccessibilityNodeInfo root=window.getRoot();if(root==null)continue;for(android.view.accessibility.AccessibilityNodeInfo match:root.findAccessibilityNodeInfosByText("Wait")){android.view.accessibility.AccessibilityNodeInfo node=match;while(node!=null){if(node.isClickable()&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){ledger.append("QA setup: accepted Wait on first-boot emulatorSystemUI dialog\n");break;}node=node.getParent();}}}getUiAutomation().waitForIdle(500,10000);}
    void persistenceSmoke()throws Exception{Intent intent=new Intent(Intent.ACTION_MAIN);intent.setComponent(new ComponentName(getTargetContext().getPackageName(),MainActivity.class.getName()));intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity activity=(MainActivity)startActivitySync(intent);waitForIdleSync();runOnMainSync(()->{check(activity.store.hasProfile(),"Profile survivesforce-stopandrestart");check(!activity.store.all("reports").isEmpty(),"Reports surviveforce-stopandrestart");check(!activity.store.all("exams").isEmpty(),"Exams surviveforce-stopandrestart");check(!activity.store.all("sessions").isEmpty(),"Planner survivesforce-stopandrestart");check(!activity.store.all("goals").isEmpty(),"Goals surviveforce-stopandrestart");activity.navigate("home");check(activity.content.getChildCount()>0,"Home remainsusableafterrestart");});dismissEmulatorDialog();capture("qa-home-restart.png");for(String screen:Arrays.asList("exams","planner","cards","settings")){runOnMainSync(()->activity.navigate(screen));waitForIdleSync();getUiAutomation().waitForIdle(500,10000);capture("qa-"+screen+".png");}}
}
